    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        int N = sc.nextInt();

        ArrayList<Integer>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 1; i <= N; i++) {
            int m = sc.nextInt();
            for (int k = 0; k < m; k++) {
                int x = sc.nextInt();
                if (x != i) {
                    adj[i].add(x);
                    adj[x].add(i);
                }
            }
        }

        int[] color = new int[N + 1];
        Arrays.fill(color, -1);

        int[] queue = new int[N];
        int head = 0, tail = 0;

        color[1] = 0;
        queue[tail++] = 1;

        while (head < tail) {
            int u = queue[head++];
            for (int v : adj[u]) {
                if (color[v] == -1) {
                    color[v] = 1 - color[u];
                    queue[tail++] = v;
                }
            }
        }

        StringBuilder sb = new StringBuilder();

        boolean first = true;
        for (int i = 1; i <= N; i++) {
            if (color[i] == 0) {
                if (!first) sb.append(' ');
                sb.append(i);
                first = false;
            }
        }
        sb.append('\n');

        first = true;
        for (int i = 1; i <= N; i++) {
            if (color[i] == 1) {
                if (!first) sb.append(' ');
                sb.append(i);
                first = false;
            }
        }
        sb.append('\n');

        System.out.print(sb.toString());
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
