            for (int j = 0; j < M; j++) {
                int x = Integer.parseInt(st.nextToken());
                adj[i].add(x);
                adj[x].add(i);
            }
        }
        int[] color = new int[N + 1];
        Arrays.fill(color, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        color[1] = 0;
        q.add(1);
